/**
 * Config for event layout
 * [More...](https://bryntum.com/products/schedulerpro/docs/api/SchedulerPro/view/mixin/SchedulerProEventRendering#typedef-EventLayoutConfig)
 */
type EventLayoutConfig = {
    /**
     * Event layout type. Possible values for horizontal mode are
     * `stack`, `pack` and `none`. For vertical mode: `pack`, `mixed` and `none`.
     */
    type?: 'stack'|'pack'|'mixed'|'none'
    /**
     * Horizontal mode only. This function allows manually positioning events inside the row.
     */
    layoutFn?: () => void
    /**
     * Horizontal mode only. Specifies groups order.
     */
    weights?: object
    /**
     * Horizontal mode only. Specifies a way to group events inside a row.
     */
    groupBy?: string|(() => void)
}

/**
 * Type object containing working days settings.
 * [More...](https://bryntum.com/products/schedulerpro/docs/api/SchedulerPro/widget/CalendarEditor#typedef-WorkingDays)
 */
type WorkingDays = Record<('0'|'1'|'2'|'3'|'4'|'5'|'6'), boolean> & {
    /**
     * Indicates if Sunday is a working day
     */
    0: boolean
    /**
     * Indicates if Monday is a working day
     */
    1: boolean
    /**
     * Indicates if Tuesday is a working day
     */
    2: boolean
    /**
     * Indicates if Wednesday is a working day
     */
    3: boolean
    /**
     * Indicates if Thursday is a working day
     */
    4: boolean
    /**
     * Indicates if Friday is a working day
     */
    5: boolean
    /**
     * Indicates if Saturday is a working day
     */
    6: boolean
}

