    /**
     * Identifies an object as an instance of [ResourceStore](https://bryntum.com/products/schedulerpro/docs/api/SchedulerPro/data/ResourceStore) class, or subclass thereof.
     */
    readonly isResourceStore: boolean
    /**
     * Identifies an object as an instance of [ResourceStoreMixin](https://bryntum.com/products/schedulerpro/docs/api/Scheduler/data/mixin/ResourceStoreMixin) class, or subclass thereof.
     */
